const q=async(conds)=>{const body=new URLSearchParams({conditions:JSON.stringify(conds),page:'1',page_size:'1000'});const r=await fetch('/marketing_campaigns/recipients/search_with_conditions.json',{method:'POST',credentials:'include',headers:Object.assign({'Content-Type':'application/x-www-form-urlencoded; charset=UTF-8','X-Requested-With':'XMLHttpRequest'},tok?{'X-CSRF-Token':tok}:{}),body});return r.json()};
const h=async e=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(e.toLowerCase())))].slice(0,4).map(b=>b.toString(16).padStart(2,'0')).join('');
const info={};const parts=[];
for(const id of [22625856,22625857,22625858,22625859]){const c=arr.find(x=>x.id===id);info[id]={status:c&&c.campaign_status_id,sent_at:c&&c.sent_at,req:c&&c.stats&&c.stats.requests,ou:c&&c.stats&&c.stats.opens_unique,cu:c&&c.stats&&c.stats.clicks_unique,uu:c&&c.stats&&c.stats.unsubscribes_unique};
